        }

        public static bool WriteProbeConfig(WriteStream stream, ref ProbeConfig value)
        {
            {
                uint rawValue = unchecked((uint)value.Retries);
                if (!stream.SerializeBits(ref rawValue, 32))
                {
                    return false;
                }
            }
            {
                uint enumValue = (uint)value.Preferred;
                Debug.Assert(enumValue <= 15, "value.Preferred above the enum wire range [0, 15]");
                if (!stream.SerializeBits(ref enumValue, 4))
                {
                    return false;
                }
            }
            return true;
        }

        public static bool ReadProbeConfig(ReadStream stream, ref ProbeConfig value)
        {
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 32))
                {
                    return false;
                }
                value.Retries = unchecked((int)(uint)rawValue);
            }
            {
                int enumValue = 0;
                if (!stream.SerializeInt(ref enumValue, 0, 15))
                {
                    return false;
                }
                value.Preferred = (Weapon)enumValue;
            }
            return true;
        }

        // ProbeArrayMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // ProbeArrayMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int ProbeArrayMaxBits = 588;
        public const int ProbeArrayMaxBytes = 80;

        // ZeroProbeArray: the §5 zero form — all-zero storage, which is default.
        public static void ZeroProbeArray(ref ProbeArray value)
        {
            value = default;
        }

        // InitProbeArray restores the construction form in place: zero, then the specified
        // defaults and born counts.
        public static void InitProbeArray(ref ProbeArray value)
        {
            value = default;
            {
                Span<ProbeSample> samplesSpan = value.Samples.AsSpan();
                for (int i = 0; i < 2; i++)
                {
                    InitProbeSample(ref samplesSpan[i]);
                }
            }
            InitProbeConfig(ref value.Config);
        }

        // NewProbeArray returns a ProbeArray in its construction form.
        public static ProbeArray NewProbeArray()
        {
            ProbeArray value = default;
            InitProbeArray(ref value);
            return value;
        }

        public static bool WriteProbeArray(WriteStream stream, ref ProbeArray value)
        {
            {
                Span<ProbeSample> samplesSpan = value.Samples.AsSpan();
                for (int i = 0; i < 2; i++)
                {
                    if (!WriteProbeSample(stream, ref samplesSpan[i]))
                    {
                        return false;
                    }
                }
            }
            if (!WriteProbeConfig(stream, ref value.Config))
            {
                return false;
            }
            return true;
        }

        public static bool ReadProbeArray(ReadStream stream, ref ProbeArray value)
        {
            {
                Span<ProbeSample> samplesSpan = value.Samples.AsSpan();
                for (int i = 0; i < 2; i++)
                {
                    if (!ReadProbeSample(stream, ref samplesSpan[i]))
                    {
                        return false;
                    }
                }
            }
            if (!ReadProbeConfig(stream, ref value.Config))
            {
                return false;
            }
            return true;
        }

        // HeartbeatMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // HeartbeatMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int HeartbeatMaxBits = 0;
        public const int HeartbeatMaxBytes = 0;

        // ZeroHeartbeat: the §5 zero form — all-zero storage, which is default.
        public static void ZeroHeartbeat(ref Heartbeat value)
        {
            value = default;
        }

        public static bool WriteHeartbeat(WriteStream stream, ref Heartbeat value)
        {
            // an empty body: presence is the payload (SPEC §4.6)
            return true;
        }

        public static bool ReadHeartbeat(ReadStream stream, ref Heartbeat value)
        {
            return true;
        }

        // TestMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // TestMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int TestMaxBits = 46;
        public const int TestMaxBytes = 8;

        // ZeroTest: the §5 zero form — all-zero storage, which is default.
        public static void ZeroTest(ref Test value)
        {
            value = default;
        }

        public static bool WriteTest(WriteStream stream, ref Test value)
        {
            {
                uint rawValue = value.TestA;
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
            }
            Debug.Assert(value.TestB >= 0 && value.TestB <= 1000, "value.TestB out of range [0, 1000]");
            {
                uint offsetValue = (uint)value.TestB;
                if (!stream.SerializeBits(ref offsetValue, 10))
                {
                    return false;
                }
            }
            Debug.Assert(value.TestC >= 0 && value.TestC <= 1000, "value.TestC out of range [0, 1000]");
            {
                uint offsetValue = (uint)value.TestC;
                if (!stream.SerializeBits(ref offsetValue, 10))
                {
                    return false;
                }
            }
            Debug.Assert(value.TestD >= 0 && value.TestD <= 1000, "value.TestD out of range [0, 1000]");
            {
                uint offsetValue = (uint)value.TestD;
                if (!stream.SerializeBits(ref offsetValue, 10))
                {
                    return false;
                }
            }
            return true;
        }

        public static bool ReadTest(ReadStream stream, ref Test value)
        {
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
                value.TestA = (ushort)rawValue;
            }
            {
                int rangeValue = 0;
                if (!stream.SerializeInt(ref rangeValue, 0, 1000))
                {
                    return false;
                }
                value.TestB = (short)rangeValue;
            }
            {
                int rangeValue = 0;
                if (!stream.SerializeInt(ref rangeValue, 0, 1000))
                {
                    return false;
                }
                value.TestC = (short)rangeValue;
            }
            {
                int rangeValue = 0;
                if (!stream.SerializeInt(ref rangeValue, 0, 1000))
                {
                    return false;
                }
                value.TestD = (short)rangeValue;
            }
            return true;
        }

        // BlockMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // BlockMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int BlockMaxBits = 16018;
        public const int BlockMaxBytes = 2008;

        // ZeroBlock: the §5 zero form — all-zero storage, which is default.
        public static void ZeroBlock(ref Block value)
        {
            value = default;
        }

        public static bool WriteBlock(WriteStream stream, ref Block value)
        {
            Debug.Assert(value.DataLength >= 0 && value.DataLength <= 2000, "value.DataLength out of range [0, 2000]");
            {
                uint offsetValue = (uint)value.DataLength;
                if (!stream.SerializeBits(ref offsetValue, 11))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.Data.AsSpan().Slice(0, value.DataLength)))
            {
                return false;
            }
            return true;
        }

        public static bool ReadBlock(ReadStream stream, ref Block value)
        {
            if (!stream.SerializeInt(ref value.DataLength, 0, 2000)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.Data.AsSpan().Slice(0, value.DataLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
            }
            return true;
        }

        // ChatMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // ChatMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int ChatMaxBits = 2064;
        public const int ChatMaxBytes = 264;

        // ZeroChat: the §5 zero form — all-zero storage, which is default.
        public static void ZeroChat(ref Chat value)
        {
            value = default;
        }

        public static bool WriteChat(WriteStream stream, ref Chat value)
        {
            Debug.Assert(value.TextLength >= 0 && value.TextLength <= 256, "value.TextLength out of range [0, 256]");
            {
                uint offsetValue = (uint)value.TextLength;
                if (!stream.SerializeBits(ref offsetValue, 9))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.Text.AsSpan().Slice(0, value.TextLength)))
            {
                return false;
            }
            return true;
        }

        public static bool ReadChat(ReadStream stream, ref Chat value)
        {
            if (!stream.SerializeInt(ref value.TextLength, 0, 256)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.Text.AsSpan().Slice(0, value.TextLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
                if (!ValidUtf8Text(bytes)) // malformed UTF-8 or an interior null is refused (SPEC §4.7)
                {
                    return false;
                }
            }
            return true;
        }

        // ProbeReportMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // ProbeReportMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int ProbeReportMaxBits = 141;
        public const int ProbeReportMaxBytes = 24;

        // ZeroProbeReport: the §5 zero form — all-zero storage, which is default.
        public static void ZeroProbeReport(ref ProbeReport value)
        {
            value = default;
        }

        public static bool WriteProbeReport(WriteStream stream, ref ProbeReport value)
        {
            if (!WriteProbeHeader(stream, ref value.Header))
            {
                return false;
            }
            Debug.Assert((ulong)value.Flags < 1UL << 8, "value.Flags has a mask bit above the 8-bit wire width");
            {
                uint flagsValue = (uint)value.Flags;
                if (!stream.SerializeBits(ref flagsValue, 8))
                {
                    return false;
                }
            }
            if (!WriteTest(stream, ref value.Echo))
            {
                return false;
            }
            return true;
        }

        public static bool ReadProbeReport(ReadStream stream, ref ProbeReport value)
        {
            if (!ReadProbeHeader(stream, ref value.Header))
            {
                return false;
            }
            {
                uint flagsValue = 0;
                if (!stream.SerializeBits(ref flagsValue, 8))
                {
                    return false;
                }
                value.Flags = (ProbeFlags)flagsValue;
            }
            if (!ReadTest(stream, ref value.Echo))
            {
                return false;
            }
            return true;
        }

        // TestDataMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // TestDataMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int TestDataMaxBits = 2735;
        public const int TestDataMaxBytes = 344;

        // ZeroTestData: the §5 zero form — all-zero storage, which is default.
        public static void ZeroTestData(ref TestData value)
        {
            value = default;
        }

        public static bool WriteTestData(WriteStream stream, ref TestData value)
        {
            Debug.Assert(value.A >= -100 && value.A <= 100, "value.A out of range [-100, 100]");
            {
                uint offsetValue = unchecked((uint)value.A - (uint)(-100));
                if (!stream.SerializeBits(ref offsetValue, 8))
                {
                    return false;
                }
            }
            Debug.Assert(value.B >= -100 && value.B <= 100, "value.B out of range [-100, 100]");
            {
                uint offsetValue = unchecked((uint)value.B - (uint)(-100));
                if (!stream.SerializeBits(ref offsetValue, 8))
                {
                    return false;
                }
            }
            Debug.Assert(value.C >= -100 && value.C <= 150, "value.C out of range [-100, 150]");
            {
                uint offsetValue = unchecked((uint)value.C - (uint)(-100));
                if (!stream.SerializeBits(ref offsetValue, 8))
                {
                    return false;
                }
            }
            if (!stream.SerializeBits(ref value.D, 8))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.E, 8))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.F, 8))
            {
                return false;
            }
            if (!stream.SerializeBool(ref value.G))
            {
                return false;
            }
            Debug.Assert(value.ItemsCount >= 0 && value.ItemsCount <= 16, "value.ItemsCount out of range [0, 16]");
            {
                uint offsetValue = (uint)value.ItemsCount;
                if (!stream.SerializeBits(ref offsetValue, 5))
                {
                    return false;
                }
            }
            {
                Span<int> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    Debug.Assert(itemsSpan[i] >= 0 && itemsSpan[i] <= 255, "itemsSpan[i] out of range [0, 255]");
                    {
                        uint offsetValue = (uint)itemsSpan[i];
                        if (!stream.SerializeBits(ref offsetValue, 8))
                        {
                            return false;
                        }
                    }
                }
            }
            if (!stream.SerializeFloat(ref value.FloatValue))
            {
                return false;
            }
            {
                float compressedValue = value.CompressedFloatValue;
                if (!stream.SerializeCompressedFloatPrecomputed(ref compressedValue, 1000u, 10, 10.0f, 0.0f))
                {
                    return false;
                }
            }
            if (!stream.SerializeDouble(ref value.DoubleValue))
            {
                return false;
            }
            {
                uint rawValue = unchecked((byte)value.Int8Value);
                if (!stream.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
            }
            {
                uint rawValue = unchecked((ushort)value.Int16Value);
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
            }
            {
                uint rawValue = value.Uint8Value;
                if (!stream.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
            }
            {
                uint rawValue = value.Uint16Value;
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
            }
            if (!stream.SerializeBits(ref value.Uint32Value, 32))
            {
                return false;
            }
            if (!stream.SerializeBits64(ref value.Uint64Value, 64))
            {
                return false;
            }
            {
                ulong rawValue = unchecked((ulong)value.Int64Full);
                if (!stream.SerializeBits64(ref rawValue, 64))
                {
                    return false;
                }
            }
            Debug.Assert(value.Int64Range >= -1000000000000 && value.Int64Range <= 1000000000000, "value.Int64Range out of range [-1000000000000, 1000000000000]");
            {
                ulong offsetValue = unchecked((ulong)value.Int64Range - (ulong)(-1000000000000));
                if (!stream.SerializeBits64(ref offsetValue, 41))
                {
                    return false;
                }
            }
            if (!stream.SerializeAlign())
            {
                return false;
            }
            if (!stream.SerializeBytes(value.FixedBytes.AsSpan())) // byte-aligned [N]uint8: one bulk copy
            {
                return false;
            }
            Debug.Assert(value.TextLength >= 0 && value.TextLength <= 255, "value.TextLength out of range [0, 255]");
            {
                uint offsetValue = (uint)value.TextLength;
                if (!stream.SerializeBits(ref offsetValue, 8))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.Text.AsSpan().Slice(0, value.TextLength)))
            {
                return false;
            }
            return true;
        }

        public static bool ReadTestData(ReadStream stream, ref TestData value)
        {
            if (!stream.SerializeInt(ref value.A, -100, 100))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.B, -100, 100))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.C, -100, 150))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.D, 8))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.E, 8))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.F, 8))
            {
                return false;
            }
            if (!stream.SerializeBool(ref value.G))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.ItemsCount, 0, 16)) // the count guards the loop (§6.3)
            {
                return false;
            }
            {
                Span<int> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    if (!stream.SerializeInt(ref itemsSpan[i], 0, 255))
                    {
                        return false;
                    }
                }
            }
            if (!stream.SerializeFloat(ref value.FloatValue))
            {
                return false;
            }
            if (!stream.SerializeCompressedFloatPrecomputed(ref value.CompressedFloatValue, 1000u, 10, 10.0f, 0.0f))
            {
                return false;
            }
            if (!stream.SerializeDouble(ref value.DoubleValue))
            {
                return false;
            }
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
                value.Int8Value = unchecked((sbyte)(byte)rawValue);
            }
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
                value.Int16Value = unchecked((short)(ushort)rawValue);
            }
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
                value.Uint8Value = (byte)rawValue;
            }
            {
                uint rawValue = 0;
                if (!stream.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
                value.Uint16Value = (ushort)rawValue;
            }
            if (!stream.SerializeBits(ref value.Uint32Value, 32))
            {
                return false;
            }
            if (!stream.SerializeBits64(ref value.Uint64Value, 64))
            {
                return false;
            }
            {
                ulong rawValue = 0;
                if (!stream.SerializeBits64(ref rawValue, 64))
                {
                    return false;
                }
                value.Int64Full = unchecked((long)rawValue);
            }
            if (!stream.SerializeInt64(ref value.Int64Range, -1000000000000L, 1000000000000L))
            {
                return false;
            }
            if (!stream.SerializeAlign()) // rejects nonzero padding (SPEC §4.3)
            {
                return false;
            }
            if (!stream.SerializeBytes(value.FixedBytes.AsSpan())) // byte-aligned [N]uint8: one bulk copy
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.TextLength, 0, 255)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.Text.AsSpan().Slice(0, value.TextLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
                if (!ValidUtf8Text(bytes)) // malformed UTF-8 or an interior null is refused (SPEC §4.7)
                {
                    return false;
                }
            }
            return true;
        }

        // CompressedProbeMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // CompressedProbeMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int CompressedProbeMaxBits = 24;
        public const int CompressedProbeMaxBytes = 8;

        // ZeroCompressedProbe: the §5 zero form — all-zero storage, which is default.
        public static void ZeroCompressedProbe(ref CompressedProbe value)
        {
            value = default;
        }

        public static bool WriteCompressedProbe(WriteStream stream, ref CompressedProbe value)
        {
            {
                float compressedValue = value.Boundary;
                if (!stream.SerializeCompressedFloatPrecomputed(ref compressedValue, 1000u, 10, 10.0f, 0.0f))
                {
                    return false;
                }
            }
            {
                float compressedValue = value.Offset;
                if (!stream.SerializeCompressedFloatPrecomputed(ref compressedValue, 10000u, 14, 10.0f, -5.0f))
                {
                    return false;
                }
            }
            return true;
        }

        public static bool ReadCompressedProbe(ReadStream stream, ref CompressedProbe value)
        {
            if (!stream.SerializeCompressedFloatPrecomputed(ref value.Boundary, 1000u, 10, 10.0f, 0.0f))
            {
                return false;
            }
            if (!stream.SerializeCompressedFloatPrecomputed(ref value.Offset, 10000u, 14, 10.0f, -5.0f))
            {
                return false;
            }
            return true;
        }
    }
}
